-- =====================================================================================
-- harness V3 :: seed data
-- Only rows the platform cannot work without at M0:
--   * the built-in agent template market (01 §6.3)
--   * the internal capabilities the portal adapter and the terminal expose
--
-- Ids are real UUIDv7 values (generated by harness-protocol Ids) so that the seed obeys the
-- same id contract as everything minted at runtime (01 §4).
--
-- Re-seed safety: harness_agent_template is keyed by template_key and harness_capability by
-- cap_key, so this migration is idempotent by construction (INSERT IGNORE).
-- =====================================================================================

SET NAMES utf8mb4;

-- -------------------------------------------------------------------------------------
-- Built-in agent templates (01 §6.3)
